def pre(a):
    def valid_game(x, y):
        # A finished game: winner has exactly 4 points and loser has 0-2,
        # or winner = loser + 2 with loser >= 3.
        return Or(
            And(x == 4, y >= 0, y <= 2),
            And(y == 4, x >= 0, x <= 2),
            And(y >= 3, x == y + 2),
            And(x >= 3, y == x + 2),
        )
    return And(valid_game(a[0], a[1]), valid_game(a[2], a[3]))

def post(a, r):
    # Player A wins a game exactly when A's score is higher in that game.
    a_wins_first = If(a[0] > a[1], 1, 0)
    a_wins_second = If(a[2] > a[3], 1, 0)
    return r == a_wins_first + a_wins_second
